/**
 * @file c_client.c
 * @brief Pure C99 consumer driving the zero-allocation C ABI generated by fsmc --emit-c-abi.
 */

#include <assert.h>
#include <string.h>

#include "thermal_controller_c.h"

typedef struct {
    int32_t gain;
    int32_t invocations;
} c_pid_ctx_t;

static int32_t c_compute_pwm(void* user_data, int32_t temp_c) {
    c_pid_ctx_t* ctx = (c_pid_ctx_t*)user_data;
    ctx->invocations += 1;
    int32_t duty = (temp_c - 20) * ctx->gain;
    if (duty < 0) {
        return 0;
    }
    if (duty > 100) {
        return 100;
    }
    return duty;
}

int run_c99_thermal_client(const char* expected_sha256) {
    c_pid_ctx_t ctx;
    thermal_controller_services_t srv;
    thermal_controller_fsm_t fsm;
    thermal_controller_in_ports_t in_ports;
    thermal_controller_out_ports_t out_ports;

    ctx.gain = 2;
    ctx.invocations = 0;
    srv.user_data = &ctx;
    srv.compute_pwm = c_compute_pwm;

    memset(&in_ports, 0, sizeof(in_ports));
    memset(&out_ports, 0, sizeof(out_ports));

    /* Verify spec-to-code SHA-256 attestation matches C++17 header */
    if (strcmp(thermal_controller_ir_sha256(), expected_sha256) != 0) {
        return -1;
    }

    thermal_controller_init_with_services(&fsm, &srv);
    if (thermal_controller_current_state(&fsm) != THERMAL_CONTROLLER_STATE_STANDBY) {
        return -2;
    }

    if (thermal_controller_dispatch_enable(&fsm, &in_ports, &out_ports) != THERMAL_CONTROLLER_STATUS_OK ||
        thermal_controller_current_state(&fsm) != THERMAL_CONTROLLER_STATE_REGULATING) {
        return -3;
    }

    in_ports.temp_c = 55;
    if (thermal_controller_dispatch_sample(&fsm, &in_ports, &out_ports) != THERMAL_CONTROLLER_STATUS_OK ||
        ctx.invocations != 1 || out_ports.pwm_duty != 70) {
        return -4;
    }

    thermal_controller_destroy(&fsm);
    return out_ports.pwm_duty;
}
